\label{Thm:BK26}
    Let $\mathcal{E}_{\mathbb{C}}$ be the $\mathbb{C}$-vector space spanned by all multiple Eisenstein series. Then the following results hold.
    \begin{enumerate}
        \item $\mathcal{E}=\bigoplus_{w\geq 0}\mathcal{E}_{w}$.
        \item The natural map $\mathcal{E}\otimes_{\mathbb{Q}}\mathbb{C} \twoheadrightarrow \mathcal{E}_{\mathbb{C}}$ is an isomorphism.
    \end{enumerate}

\label{thm.Goncharov-Zagier conjecture for function field}
    We keep the notation as above. Then the following results hold.
    \begin{enumerate}  
        \item $\mathcal{Z}_{\overline{K}}$ is a graded algebra, i.e.,  $\mathcal{Z}_{\overline{K}} = \bigoplus_{w=0}^{\infty} \mathcal{Z}_{\overline{K}, w}$.
        \item The natural map $\mathcal{Z}_K\otimes_K \overline{K}\to \mathcal{Z}_{\overline{K}}$ is an isomorphism.
    \end{enumerate}

\label{thm.main-thm}
    For any integer $r\geq 1$, the following results hold.
    \begin{itemize}
        \item[(i)]  $\mathcal{Z}^{(r)}_{\overline{K}}$ is a graded algebra, i.e.,  \[\mathcal{Z}^{(r)}_{\overline{K}} = \bigoplus_{w=0}^{\infty}\mathcal{Z}^{(r)}_{\overline{K},w}.\]
        \item[(ii)] The natural map $\mathcal{Z}^{(r)}_{K}\otimes_K \overline{K}\twoheadrightarrow  \mathcal{Z}^{(r)}_{\overline{K}}$ is an isomorphism of $\overline{K}$-algebras. 
    \end{itemize}

\label{df.Goss polynomial}
    Fix $r\ge 1$ and an $A$-lattice $\Lambda$ of rank $r$ in $\mathbb{C}_{\infty}$.
    We define the Goss polynomials by the sequence of polynomials $\{G_k^{\Lambda}(X)\}_{k=1}^{\infty}$ in $\mathbb{C}_{\infty}[X]$ satisfying the following recurrence:
    \begin{enumerate}
        \item $G_1^{\Lambda}(X) = X$, and
        \item for an integer $k > 1$, 
        \[
        G_k^{\Lambda}(X) = X\sum_{q^i<k}e_i(\Lambda)G_{k-q^i}^{\Lambda}(X).
        \]
    \end{enumerate}

\label{prop.G_a(t(X)) = sum 1/(X+λ)^a}
    For any integer $k\geq 1$, the following properties hold.
    \begin{enumerate}
        \item $G_k^{\Lambda_{\mathbf{z}}}(t_{\Lambda_{\mathbf{z}}}(X)) = \sum_{\lambda\in \Lambda_{\mathbf{z}}}\frac{1}{(X+\lambda)^k}$.
        \item $G_k^{\Lambda_{\mathbf{z}}}(X)$ is a monic polynomial of degree $k$.
        \item $X\mid G_k^{\Lambda_{\mathbf{z}}}(X)$.
        \item if $1\le k\le q$, $G_k^{\Lambda_{\mathbf{z}}}(X) = X^k$.
    \end{enumerate}

\label{df.a^(i) and a_(i)}
    For a nonempty index $\mathfrak{s}=(s_1,\ldots,s_m)$ and $i\geq0$, we let
    \[
    \mathfrak{s}^{(i)}
    =
    \begin{cases}
    \mathfrak{s}, & i=0,\\
    (s_{i+1},\ldots,s_m), & 1\leq i<m,\\
    \varnothing, & i\geq m,
    \end{cases}
    \qquad\text{and}\qquad
    \mathfrak{s}_{(i)}
    =
    \begin{cases}
    \varnothing, & i=0,\\
    (s_1,\ldots,s_i), & 1\leq i<m,\\
    \mathfrak{s}, & i\geq m.
    \end{cases}
    \]

\label{thm.main-thm over C_infty}
    Fix a positive integer $r\geq 2$.
    Then the following results hold.
    \begin{enumerate}
        \item $\mathcal{Z}^{(r)}_{\mathbb{C}_\infty}$ is a graded algebra, i.e.,  \[\mathcal{Z}^{(r)}_{\mathbb{C}_\infty} = \bigoplus_{w=0}^{\infty}\mathcal{Z}^{(r)}_{\mathbb{C}_\infty,w}.\]
        \item The natural map $\mathcal{Z}^{(r)}_{K}\otimes_K \mathbb{C}_\infty\twoheadrightarrow  \mathcal{Z}^{(r)}_{\mathbb{C}_\infty}$ is an isomorphism of $\mathbb{C}_\infty$-algebras. 
    \end{enumerate}

\label{lem:comparison between >_N and >}
    Let $\bm{f},\bm{g}\in A^r$ be nonzero with
    $|\bm{f}|,|\bm{g}|<q^N$. Then
    \begin{enumerate}
        \item $\bm{f}\succ_N0$ if and only if $\bm{f}\succ0$.
        \item $\bm{f}\succ_N\bm{g}$ if and only if $\bm{f}\succ\bm{g}$.
    \end{enumerate}

\label{df.shifted MES}
    For any nonempty index $\mathfrak{s}=(s_1,\ldots,s_m)$, we define
    \[
    E_r^{\langle N\rangle}(\mathfrak{s};\mathbf{z})
    =
    \sum_{\substack{
    \bm{f}_1,\ldots,\bm{f}_m\in A^r\\
    \bm{f}_1\succ_N\cdots\succ_N\bm{f}_m\succ_N0
    }}
    \frac{1}{
    \langle\bm{f}_1,\mathbf{z}\rangle^{s_1}
    \cdots
    \langle\bm{f}_m,\mathbf{z}\rangle^{s_m}
    }.
    \]
    By convention, we put $E_r^{\langle N \rangle}(\varnothing;\mathbf{z})=1$.

We may assume $\mathfrak{s}=(s_1,\ldots,s_m)$ is nonempty. By
\cref{lem:comparison between >_N and >}, the two summation sets
defining $E_r^{\langle N\rangle}(\mathfrak{s};\mathbf{z})$ and
$E_r(\mathfrak{s};\mathbf{z})$ agree whenever
\[
|\bm{f}_1|,\ldots,|\bm{f}_m|<q^N.
\]
Hence their difference is supported on tuples for which
$|\bm{f}_i|\geq q^N$ for some $1\leq i\leq m$.
On the other hand, notice that for each fixed $\mathbf{z}\in\Omega^r$, the $K_\infty$-linear map
\[
K_\infty^r\longrightarrow\mathbb{C}_\infty,
\qquad
\bm{f}\longmapsto\langle\bm{f},\mathbf{z}\rangle,
\]
is injective. Since $K_\infty^r$ is finite-dimensional, there exists
$c_0(\mathbf{z})>0$ such that
\[
|\langle\bm{f},\mathbf{z}\rangle|
\geq
c_0(\mathbf{z})|\bm{f}|
\qquad
(\bm{f}\in K_\infty^r).
\]
Thus, a standard estimate shows that there exists a constant $c(\mathbf{z})>0$, independent of $N$, such that
\[
\left|
E_r^{\langle N\rangle}(\mathfrak{s};\mathbf{z})
-
E_r(\mathfrak{s};\mathbf{z})
\right|
\leq
c(\mathbf{z})q^{-N}.
\]
This proves (i).

    For (ii), one checks that
    \[
    \gamma_N\mathbf{z}_N^{\operatorname{tr}}
    =
    j_N(\mathbf{z})^{-1}\mathbf{z}^{\operatorname{tr}},
    \]
    which implies $\mathbf{z}_{N}\in \Omega^{r}$.
    It follows that
    \begin{align*}
    E_r(\mathfrak{s};\mathbf{z}_N)
    &=
    \sum_{\substack{
    \bm{f}_1,\ldots,\bm{f}_m\in A^r\\
    \bm{f}_1\succ\cdots\succ\bm{f}_m\succ0
    }}
    \frac{1}{
    (\bm{f}_1\mathbf{z}_N^{\operatorname{tr}})^{s_1}
    \cdots
    (\bm{f}_m\mathbf{z}_N^{\operatorname{tr}})^{s_m}
    }
    \\
    &=
    j_N(\mathbf{z})^{\operatorname{wt}(\mathfrak{s})}
    \sum_{\substack{
    \bm{f}_1,\ldots,\bm{f}_m\in A^r\\
    \bm{f}_1\succ\cdots\succ\bm{f}_m\succ0
    }}
    \frac{1}{
    (\bm{f}_1\gamma_N^{-1}\mathbf{z}^{\operatorname{tr}})^{s_1}
    \cdots
    (\bm{f}_m\gamma_N^{-1}\mathbf{z}^{\operatorname{tr}})^{s_m}
    }
    \\
    &=
    j_N(\mathbf{z})^{\operatorname{wt}(\mathfrak{s})}
    \sum_{\substack{
    \bm{f}_1,\ldots,\bm{f}_m\in A^r\\
    \bm{f}_1\succ\cdots\succ\bm{f}_m\succ0
    }}
    \frac{1}{
    \langle \bm{f}_1\gamma_N^{-1},\mathbf{z} \rangle^{s_1}
    \cdots
    \langle \bm{f}_m\gamma_N^{-1},\mathbf{z} \rangle^{s_m}
    }
    \\
    &=
    j_N(\mathbf{z})^{\operatorname{wt}(\mathfrak{s})}
    \sum_{\substack{
    \bm{f}_1,\ldots,\bm{f}_m\in A^r\\
    \bm{f}_1\succ_N\cdots\succ_N\bm{f}_m\succ_N0
    }}
    \frac{1}{
    \langle\bm{f}_1,\mathbf{z}\rangle^{s_1}
    \cdots
    \langle\bm{f}_m,\mathbf{z}\rangle^{s_m}
    }
    \\
    &=
    j_N(\mathbf{z})^{\operatorname{wt}(\mathfrak{s})}
    E_r^{\langle N\rangle}(\mathfrak{s};\mathbf{z}),
    \end{align*}
    where the fourth equality follows by the change of variables
    $\bm{f}_i\mapsto\bm{f}_i\gamma_N^{-1}$ and the definition of
    $\succ_N$. This proves (ii).

\label{prop.Gcal is defined over K}
    For every integer $w\ge 0$, the natural map
    \[
    \widetilde{\mathcal{G}}_{K,\le w}^{(2)} \otimes_K \mathbb{C}_\infty \xrightarrow{\sim} \widetilde{\mathcal{G}}_{\mathbb{C}_\infty, \le w}^{(2)}
    \]
    is an isomorphism.
